const end = new Date();
const start = new Date(end.getTime() - 7 * 24 * 60 * 60 * 1000);
const repository = String($env.MSIME_GITHUB_REPOSITORY ?? '');
if (!repository || !$env.MSIME_GITHUB_TOKEN) {
  throw new Error('缺少周报所需的 GitHub 配置');
}
const date = (value) => value.toISOString().slice(0, 10);
return [{json: {
  period_start: date(start),
  period_end: date(end),
  start_at: start.getTime(),
  end_at: end.getTime(),
  repository,
  umami_base_url: String($env.MSIME_UMAMI_BASE_URL ?? '').replace(/\/$/, ''),
  website_id: String($env.MSIME_UMAMI_WEBSITE_ID ?? ''),
  umami_enabled: $env.MSIME_UMAMI_ENABLED === '1',
  install_enabled: $env.MSIME_UMAMI_INSTALL_ENABLED === '1',
  install_event: String($env.MSIME_UMAMI_INSTALL_EVENT ?? 'Install')
}}];

const period = $('准备查询').first().json;
if (!period.umami_enabled) return [{json: {downloads: null, installs: null, period}}];
const queries = $('准备转化查询').all();
const metrics = {downloads: [], installs: period.install_enabled ? [] : null};
for (const [index, item] of $input.all().entries()) {
  const query = queries[index].json;
  const body = item.json.body ?? item.json;
  const events = body.data?.events;
  const failed = item.json.error || Number(item.json.statusCode ?? 200) >= 400 || typeof events !== 'number' || !Number.isFinite(events) || events < 0;
  const row = {utmSource: query.source || 'unknown', events};
  if (failed) metrics[query.kind] = {error: true};
  else if (Array.isArray(metrics[query.kind]) && (query.source || events > 0)) metrics[query.kind].push(row);
}
return [{json: {...metrics, period}}];

const input = $json;
const period = input.period ?? {};
const response = value => value && typeof value === 'object' && value.body && typeof value.body === 'object' ? value.body : value;
const traffic = response(input.traffic);
const downloads = input.downloads;
const installs = input.installs;
const github = response(input.github);
const releases = response(input.releases);
const failed = value => Boolean(value?.error) || Number(value?.statusCode ?? 200) >= 400;
const number = value => Number.isFinite(Number(value)) ? Number(value) : 0;
const rows = value => Array.isArray(value) ? value : (Array.isArray(value?.data) ? value.data : (Array.isArray(value?.results) ? value.results : []));
const grouped = new Map();
const sourceRow = source => {
  if (!grouped.has(source)) grouped.set(source, {visitors: 0, visits: 0, downloads: downloads === null || failed(downloads) ? null : 0, installs: installs === null || failed(installs) ? null : 0});
  return grouped.get(source);
};
for (const row of rows(traffic)) {
  const current = sourceRow(String(row.utmSource || 'unknown'));
  current.visitors += number(row.visitors);
  current.visits += number(row.visits);
}
for (const [kind, value] of [['downloads', downloads], ['installs', installs]]) {
  for (const row of rows(value)) sourceRow(String(row.utmSource || 'unknown'))[kind] += number(row.events);
}
const platformRows = [...grouped.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([source, values]) => ({source, ...values}));
const state = $getWorkflowStaticData('global');
const githubFailed = failed(input.github) || !github || typeof github.stargazers_count !== 'number' || typeof github.forks_count !== 'number';
const stars = githubFailed ? null : github.stargazers_count;
const forks = githubFailed ? null : github.forks_count;
const delta = (current, previous) => current !== null && typeof previous === 'number' && Number.isFinite(previous) ? current - previous : null;
const starDelta = delta(stars, state.last_stars);
const forkDelta = delta(forks, state.last_forks);
if (!githubFailed) {
  state.last_stars = stars;
  state.last_forks = forks;
  state.last_snapshot_at = new Date().toISOString();
}
const start = String(period.period_start ?? '').slice(0, 10);
const end = String(period.period_end ?? '').slice(0, 10);
const formatDelta = value => value === null ? '首次记录' : (value >= 0 ? `+${value}` : String(value));
const count = value => value === null ? '不可用' : String(value);
const trafficFailed = failed(input.traffic);
const trafficText = row => trafficFailed ? '访问数据不可用' : `访问人数 ${row.visitors}，访问次数 ${row.visits}`;
const platformText = platformRows.length ? platformRows.map(row => `- ${row.source}：${trafficText(row)}，下载点击 ${count(row.downloads)}${period.install_enabled ? `，安装事件 ${count(row.installs)}` : ''}`).join('\n') : (trafficFailed ? '- 官网访问数据不可用' : '- 暂无带 social UTM 的访问数据');
const releaseFailed = failed(input.releases) || !Array.isArray(releases);
const releaseList = Array.isArray(releases) ? releases.filter(release => { const published = Date.parse(release.published_at); return published >= period.start_at && published <= period.end_at; }) : [];
const releaseText = releaseFailed ? '- Release 数据不可用' : (releaseList.length ? releaseList.map(release => `- ${release.tag_name ?? release.name ?? '未命名版本'}（${String(release.published_at ?? '').slice(0, 10)}）`).join('\n') : '- 本周期没有新 Release');
const failures = [['官网访问', input.traffic], ['下载点击', downloads], ['安装事件', installs], ['GitHub 仓库', input.github], ['GitHub Release', input.releases]].filter(([, value]) => failed(value)).map(([name]) => `- ${name}查询失败，本项数据不可用`);
const githubText = githubFailed ? ['- GitHub 仓库数据不可用'] : [`- Star：${stars}（较上次快照 ${formatDelta(starDelta)}）`, `- Fork：${forks}（较上次快照 ${formatDelta(forkDelta)}）`];
const report = [`水杉输入法社交效果周报（${start} 至 ${end}）`, '', '平台数据（按 utm_source 汇总）', platformText, '- 下载点击只代表点击，不代表下载完成或安装。', ...(!period.install_enabled ? ['- 安装数据尚未接入，不显示为零安装。'] : []), ...(period.umami_enabled === false ? ['- Umami 查询未启用，官网访问与下载点击数据不可用。'] : []), '', 'GitHub 整体变化（无法归因到单个平台）', ...githubText, '', `本周期 Release${releaseFailed ? '' : `（${releaseList.length} 个）`}`, releaseText, ...(failures.length ? ['', '查询状态', ...failures] : [])].join('\n');
return [{json: {report, report_period_start: period.period_start, report_period_end: period.period_end, platform_rows: platformRows, star_delta: starDelta, fork_delta: forkDelta, release_count: releaseFailed ? null : releaseList.length}}];

const input = $json.body ?? $json;
const rows = Array.isArray(input) ? input : [];
const sources = [...new Set(rows.map(row => String(row.utmSource ?? '')).filter(Boolean))];
const period = $('准备查询').first().json;
const events = [{kind: 'downloads', event: 'Download'}];
if (period.install_enabled) events.push({kind: 'installs', event: period.install_event});
return (sources.length ? sources : ['']).flatMap(source => events.map(event => ({json: {source, ...event}})));
